draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(10, 10, W-20, H-20);
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(20, H/2);
  ctx.lineTo(W-20, H/2);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Blackboard', 20, 20);
  ctx.fillStyle = '#ccc';
  ctx.fillRect(W-150, 20, 120, 50);
  ctx.fillStyle = 'black';
  ctx.fillText('Teacher\'s Desk', W-140, 25);
  ctx.restore();
}
